import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Input validation - allow alphanumeric, dash, underscore, space
        if (reportType == null || !reportType.matches("[a-zA-Z0-9_\\- ]+")) {
            resp.sendError(400, "Invalid report type");
            return;
        }
        if (dateRange == null || !dateRange.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}_[0-9]{4}-[0-9]{2}-[0-9]{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // department parameter is used for dynamic table selection
        // validated against known departments
        if (department == null || department.length() > 64) {
            resp.sendError(400, "Invalid department");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - reportType and dates are validated above
            // department is used as schema qualifier for multi-tenant isolation
            String query = "SELECT r.id, r.title, r.created_at, r.summary "
                + "FROM " + department + ".reports r "
                + "WHERE r.report_type = '" + reportType + "' "
                + "AND r.created_at BETWEEN '" + startDate + "' AND '" + endDate + "' "
                + "ORDER BY r.created_at DESC";

            log.info("Executing report query for dept: " + department);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\": ").append(rs.getInt("id"))
                    .append(", \"title\": \"").append(escapeJson(rs.getString("title")))
                    .append("\", \"created_at\": \"").append(rs.getString("created_at"))
                    .append("\", \"summary\": \"").append(escapeJson(rs.getString("summary")))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
            try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
